function showPhoto(id){const p=getPhoto(id);if(!p)return;action('photo_open',{photoId:id});const r=s.results?.find(r=>r.id===id);showModal(`<div class="photo-detail"><div class="detail-image"><img src="${H(p.src)}" alt="${H(p.caption||p.title)}"></div><div class="detail-copy"><div class="detail-top"><span class="badge ${p.source==='sample'?'warm':'green'}">${p.source==='sample'?'ILLUSTRATED SAMPLE':'YOUR SELECTED PHOTO'}</span><button class="dialog-close" data-action="close-modal" aria-label="Close photo">×</button></div><h2 id="dialog-title">${H(p.title)}</h2><p>${H(p.date||'Date not supplied')} · ${H(p.eventLabel||p.eventType||'Unsorted')}${p.source==='sample'?' · fictional metadata':''}</p><p>${H(p.caption||'No description yet. Add one below, or use AI analysis.')}</p><h4>${r?'Why it appeared':'Visible / supplied clues'}</h4>${r?.evidence?.length?r.evidence.map(t=>`<div class="detail-evidence">“${H(t)}”</div>`).join(''):`<div class="matched-cues">${(p.cues||[]).map(c=>`<span>${H(c)}</span>`).join('')||'<span>No cues supplied</span>'}</div>`}${r?.missing?.length?`<p class="missing-note">Not established: ${H(r.missing.join(', '))}</p>`:''}${p.people?.length?`<h4>Manual people tags</h4><p>${H(p.people.join(', '))} — ${p.source==='sample'?'fictional fixture labels':'provided by you, not face recognition'}</p>`:''}<div class="detail-actions">${activeAttempt()?`<button class="button success" data-action="confirm-photo" data-id="${H(id)}">${icon('check')} This is the photo</button><button class="button" data-action="reject-modal" data-id="${H(id)}">Not this photo</button>`:`<button class="button primary" data-action="go-search">Start a retrieval search</button>`}<button class="button ghost" data-action="related" data-id="${H(id)}">Explore this moment →</button><a class="button ghost" href="${H(p.src)}" download="${H(p.title.replace(/[^a-zA-Z0-9 -]/g,'')||'memory')}.jpg">${icon('download')} Save resized image</a></div><p class="mode-note">${p.source==='sample'?'Cropped from the case-study illustrations. Names, groups and dates were authored for this demo.':'AI descriptions and inferred event categories may be wrong. You can correct them below. Only you can identify this memory.'}</p>${p.source!=='sample'?`<details><summary>Edit the photo’s context</summary><form id="edit-photo-form" data-id="${H(id)}"><div class="field"><label for="edit-title">Title</label><input id="edit-title" maxlength="120" value="${H(p.title)}"></div><div class="field"><label for="edit-caption">What is visible?</label><textarea id="edit-caption" maxlength="1000">${H(p.caption||'')}</textarea></div><div class="field"><label for="edit-cues">Visual clues, comma-separated</label><input id="edit-cues" maxlength="1000" value="${H((p.cues||[]).join(', '))}"></div><div class="field"><label for="edit-event">Event / moment label</label><input id="edit-event" maxlength="120" value="${H(p.eventLabel||'')}"></div><div class="field"><label for="edit-type">Event category</label><select id="edit-type">${E.EVENT_TYPES.map(t=>`<option ${p.eventType===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="edit-setting">Setting</label><select id="edit-setting">${['unknown','indoor','outdoor'].map(t=>`<option ${p.setting===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="edit-people">People you identify, comma-separated</label><input id="edit-people" maxlength="600" value="${H((p.people||[]).join(', '))}"><small>Never inferred by the model.</small></div><div class="field"><label for="edit-date">Date (optional)</label><input id="edit-date" type="date" value="${H(p.date||'')}"></div><button class="button primary small" type="submit">Save context</button></form><div class="inline-actions"><button class="text-button" data-action="delete-photo" data-id="${H(id)}">Delete this browser copy</button></div></details>`:''}</div></div>`,'photo-dialog');}
function confirmPhoto(id){if(!activeAttempt())return;endAttempt('confirmed',id);const a=attempt(),p=getPhoto(id);showModal(`<div class="success-panel"><div class="success-icon" aria-hidden="true">✓</div><h2 id="dialog-title">Back to that moment.</h2><p>You confirmed this photo in ${((a.endedAt-a.startedAt)/1000).toFixed(1)} seconds.<br>${a.targetId?(a.targetId===id?'This selection matches the facilitator’s preselected target.':'This selection does not match the facilitator’s preselected target.'):'Recorded as a user confirmation—not independently verified success.'}</p><img src="${H(p.src)}" alt="${H(p.caption||p.title)}"><div class="inline-actions"><button class="button primary" data-action="new-search">Find another memory</button><button class="button" data-action="open-insights">See test insights</button></div><button class="text-button" data-action="undo-confirm">Actually, this isn’t the one — undo</button></div>`);render();}
