function showConsent(next){showModal(`<div class="dialog-content">${dialogHead('Use AI with your selected photos?')}<p>For search, your memory query, stored photo descriptions and manual labels will be sent through this server to Google Gemini. Image pixels are sent only when you request image analysis.</p><p>The server does not write photos or descriptions to disk. The provider processes the request under your API account’s terms. Use photos you have permission to share; remove sensitive images before a public test.</p><label class="checkbox-row"><input id="consent-confirm" type="checkbox"><span>I understand and permit this processing for this browser session.</span></label><div class="inline-actions"><button class="button primary" data-action="grant-consent" data-next="${H(next)}">Continue with AI</button><button class="button" data-action="close-modal">Not now</button></div></div>`);}
function showPrivacy(){showModal(`<div class="dialog-content">${dialogHead('Your photos. Your control.')}<h3>On this device</h3><p>Selected JPEG, PNG and WebP photos are resized to a maximum of 1,600 pixels per edge and stored in this browser’s IndexedDB. Your search trail is stored locally. This is not encrypted storage; avoid shared browser profiles.</p><h3>When you enable AI</h3><p>Analysis sends a resized photo to the app server and Google Gemini. Later searches send your query, descriptions and manual labels—not the pixels again. You approve these actions. The app server keeps no persistent photo database.</p><h3>What this MVP does not do</h3><p>It does not connect to Google Photos, recognize identities, auto-import your library, extract EXIF, or generate missing photos. Manually supplied people tags are the only source of names. Suggested event groups may combine unrelated photos.</p><h3>Sample collection</h3><p>Illustrations are cropped from the uploaded case-study deck. Sample names, dates and groups are fictional test fixtures, not interview data.</p><div class="inline-actions"><button class="button primary" data-action="close-modal">Back to my memories</button><button class="button" data-action="clear-all">Delete local data</button></div></div>`);}
function showUpload(){pendingFiles=[];stopImport=false;showModal(`<div class="dialog-content">${dialogHead('Bring a few memories','Start with one occasion. Up to 100 photos in this browser.')}<div id="dropzone" class="dropzone">${icon('upload')}<h3>Choose photos, or drop them here</h3><p>JPEG, PNG or WebP · up to 20 MB each before resizing</p><input id="photo-files" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-label="Select photos"><div id="file-selection" class="upload-status">No photos selected</div></div><div class="form-grid"><div class="field"><label for="upload-event">A name for this moment (optional)</label><input id="upload-event" maxlength="120" placeholder="Birthday at home"><small>Leave blank to use suggested groupings.</small></div><div class="field"><label for="upload-date">Date, only if you know it</label><input id="upload-date" type="date"><small>Never guessed from a filename or upload time.</small></div></div><div class="field"><label for="upload-people">People in every selected photo (optional)</label><input id="upload-people" maxlength="600" placeholder="Add manual names only when true for all selected photos"><small>These labels do not perform face recognition. You can tag photos individually later.</small></div><label class="checkbox-row"><input id="analyze-on-upload" type="checkbox" ${!s.configured?'disabled':''}><span><b>Describe these images with Gemini</b><small>I permit sending resized copies to this server and Google Gemini. Descriptions can be edited. ${!s.configured?'Configure the server key in AI settings first.':'This uses approximately one AI call per image.'}</small></span></label><p>Resized copies stay in this browser until you delete them. Use images you have permission to share.</p><div class="inline-actions"><button class="button primary" id="import-button" data-action="import">Add selected photos</button><button class="button" data-action="close-modal">Cancel</button></div><progress id="upload-progress" value="0" max="1" class="hidden" aria-label="Import progress"></progress><div id="upload-status" class="upload-status" role="status"></div></div>`);}
function selectFiles(list){pendingFiles=[...list];$('#file-selection').textContent=`${pendingFiles.length} ${pendingFiles.length===1?'file':'files'} selected`;}
async function resized(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error(`${file.name}: choose JPEG, PNG or WebP (export HEIC as JPEG first).`);
 if(file.size>20*1024*1024)throw new Error(`${file.name}: over the 20 MB import limit.`);
 const url=URL.createObjectURL(file);try{const im=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=()=>reject(new Error(`${file.name}: could not decode this image.`));x.src=url;});if(im.width*im.height>100000000)throw new Error(`${file.name}: image dimensions are too large.`);const scale=Math.min(1,1600/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(im,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.85);if(src.length>5.3*1024*1024)throw new Error(`${file.name}: resized copy is too large.`);const hash=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(src)))).map(b=>b.toString(16).padStart(2,'0')).join(''):null;return {src,hash};}finally{URL.revokeObjectURL(url);}
}
function setUploadStatus(message,value,max){const t=$('#upload-status');if(t)t.textContent=message;const p=$('#upload-progress');if(p){p.classList.remove('hidden');p.max=max||1;p.value=value||0;}}
function groupKey(p){return p.eventLabel?'manual:'+E.normalize(p.eventLabel)+':'+p.date:'suggested:'+p.eventType+':'+(p.date||'undated')+':'+p.setting;}
async function analyzePhoto(p){const data=await api('/api/analyze',{image:p.src});p.caption=data.caption;p.cues=data.cues;p.eventType=data.eventType;p.setting=data.setting;p.indexed='ai';p.analysisMeta=data.meta;p.eventId=groupKey(p);await storePhoto(p);s.aiChecked=true;return p;}
async function performImport(){
 if(importBusy)return;if(!pendingFiles.length){toast('Choose at least one photo.');return;}if(s.own.length+pendingFiles.length>100){toast(`There is room for ${100-s.own.length} more photos. Choose a smaller batch.`);return;}
 const analyze=$('#analyze-on-upload')?.checked&&s.configured;if(analyze&&s.requiresToken&&!s.reviewerToken){showSettings();toast('Set the reviewer password, then select your photos again.');return;}
 const eventLabel=$('#upload-event').value.trim(),date=$('#upload-date').value,people=$('#upload-people').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,12);
 importBusy=true;stopImport=false;$('#import-button').disabled=true;$('#photo-files').disabled=true;let added=0,failed=0,duplicates=0,indexFailed=0;const errors=[];
 for(let i=0;i<pendingFiles.length;i++){
  if(stopImport)break;const file=pendingFiles[i];setUploadStatus(`${analyze?'Importing and describing':'Importing'} ${i+1} of ${pendingFiles.length}…`,i,pendingFiles.length);
  try{const image=await resized(file);if(image.hash&&s.own.some(p=>p.hash===image.hash)){duplicates++;continue;}
   const p={id:'photo-'+E.uid(),title:file.name.replace(/\.[^.]+$/,'').slice(0,120),src:image.src,hash:image.hash,date,eventLabel,eventType:'unknown',eventId:'',people:[...people],setting:'unknown',caption:'',cues:[],source:'upload',indexed:'manual'};p.eventId=groupKey(p);
   await storePhoto(p);s.own.push(p);added++;
   if(analyze){try{await analyzePhoto(p);}catch(e){indexFailed++;errors.push(e.message);}}
  }catch(e){failed++;errors.push(e.message);}setUploadStatus(`Added ${added} photos. ${indexFailed?'AI description failed for '+indexFailed+'; originals remain available.':''}`,i+1,pendingFiles.length);
 }
 importBusy=false;s.consent=s.consent||Boolean(analyze);resetSearch();s.collection='upload';s.view='library';s.eventFilter='all';render();
 const message=`${added} photos added${duplicates?' · '+duplicates+' duplicate copies skipped':''}${failed?' · '+failed+' import failures':''}${indexFailed?' · '+indexFailed+' AI descriptions failed':''}${stopImport?' · stopped early':''}.`;
 showModal(`<div class="dialog-content">${dialogHead('Your collection is ready to explore')}<p>${H(message)}</p>${errors.length?`<div class="banner error">${errors.slice(0,4).map(H).join('<br>')}<br>Unindexed photos can be described later from My collection.</div>`:''}<p>${analyze?'Review AI descriptions for mistakes before testing.':'Add descriptions and labels by opening a photo, or use “Describe unindexed photos with AI.” Without descriptions, visual memory searches cannot find their contents.'}</p><div class="inline-actions"><button class="button primary" data-action="go-search">Find a memory</button><button class="button" data-action="close-modal">Review my collection</button></div></div>`);
}
async function indexPending(){if(!s.configured){showSettings();return;}if(s.requiresToken&&!s.reviewerToken){showSettings();return;}showModal(`<div class="dialog-content">${dialogHead('Describe your selected photos','Review AI descriptions afterwards; they can be wrong.')}<p>This will send ${s.own.filter(p=>p.indexed!=='ai').length} resized images through this server to Google Gemini. Photos already described by AI will be skipped. People names and exact dates are never inferred.</p><label class="checkbox-row"><input id="index-consent" type="checkbox"><span>I permit this image processing under my Gemini account’s terms.</span></label><button class="button primary" data-action="confirm-index">Describe images</button><div id="index-status" class="status-message" role="status"></div></div>`);}
async function doIndex(){if(!$('#index-consent')?.checked){toast('Confirm permission before sending images.');return;}if(importBusy)return;importBusy=true;stopImport=false;const pending=s.own.filter(p=>p.indexed!=='ai');let ok=0,failed=0,last='';const button=$('[data-action="confirm-index"]');button.disabled=true;for(let i=0;i<pending.length;i++){if(stopImport)break;$('#index-status').textContent=`Describing photo ${i+1} of ${pending.length}…`;try{await analyzePhoto(pending[i]);ok++;}catch(e){failed++;last=e.message;}}importBusy=false;s.consent=true;$('#index-status').textContent=`${ok} described · ${failed} failed. ${last} ${stopImport?'Stopped early.':''}`;button.disabled=false;button.textContent='Retry remaining';render();}
function showTestSetup(){const items=photos();if(!items.length){showUpload();return;}showModal(`<div class="dialog-content">${dialogHead('Set up a retrieval test','Facilitator: choose the target before handing the screen to the participant.')}<p>This records one task, not a completed user study. Use an anonymous code. Ask the participant to describe a genuinely remembered photo without revealing its filename.</p><form id="test-form"><div class="field"><label for="test-code">Participant code (optional)</label><input id="test-code" maxlength="30" placeholder="P01 — no real names"></div><div class="field"><label for="test-target">Intended target in this collection</label><select id="test-target">${items.map(p=>`<option value="${H(p.id)}">${H(p.title)}</option>`).join('')}</select></div><p>The target is used only for exact-ID outcome checking; it is never sent to the search model or used to rank results.</p><div class="inline-actions"><button class="button primary" type="submit">Begin participant task</button><button class="button" type="button" data-action="close-modal">Cancel</button></div></form></div>`);}
