async function clearAll(){if(!confirm('Delete all uploaded photo copies and all search history from this browser? This cannot be undone. The sample illustrations remain.'))return;try{const d=await db();await new Promise((resolve,reject)=>{const t=d.transaction('photos','readwrite');t.objectStore('photos').clear();t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}catch(e){toast('Could not clear photo storage: '+e.message);return;}cancelSearch();s.own=[];s.attempts=[];s.attemptId=null;s.pendingTest=null;s.consent=false;s.reviewerToken='';try{sessionStorage.removeItem('memorytrail5-reviewer');}catch{}persist();resetSearch(false);s.collection='sample';s.view='search';closeModal();render();toast('Uploaded copies and search history deleted from this browser.');}
function voice(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice input is not supported in this browser. Type your memory instead.');return;}if(!confirm('Voice recognition may send audio to your browser’s speech service. Allow voice input for this query?'))return;const r=new Recognition();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const input=$('#memory-input');if(input){input.value=e.results[0][0].transcript;input.focus();}toast('Voice text added. Review it before searching.');};r.onerror=e=>toast('Voice input stopped: '+e.error+'. You can still type.');r.onend=()=>{};try{r.start();toast('Listening…');}catch{toast('Microphone could not start. Type your memory instead.');}}
// Central event delegation keeps the UI free of inline handlers and works under CSP.
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const act=el.dataset.action;
 try{
  switch(act){
   case 'nav': if(s.busy)cancelSearch();s.view=el.dataset.view;s.eventFilter='all';render();break;
   case 'collection': if(el.dataset.collection===s.collection)break;resetSearch();s.pendingTest=null;s.collection=el.dataset.collection;render();break;
   case 'example': resetSearch();await runSearch(el.dataset.query);break;
   case 'suggestion': action('suggestion',{text:el.dataset.query});await runSearch(el.dataset.query);break;
   case 'focus-query': $('#memory-input')?.focus();break;
   case 'new-search': resetSearch();s.pendingTest=null;s.view='search';closeModal();render();break;
   case 'go-search': closeModal();s.view='search';render();break;
   case 'browse-library': s.view='library';render();break;
   case 'certainty': {const clues=E.clone(s.clues),i=Number(el.dataset.index);if(!clues[i])break;clues[i].certainty=clues[i].certainty==='maybe'?'certain':'maybe';action('clue_certainty',{text:clues[i].text,certainty:clues[i].certainty});await runSearch('Apply my edited memory clues.',{override:clues});break;}
   case 'toggle-clue': {const clues=E.clone(s.clues),i=Number(el.dataset.index);if(!clues[i])break;clues[i].enabled=clues[i].enabled===false;action('clue_toggle',{text:clues[i].text,enabled:clues[i].enabled});await runSearch('Apply my edited memory clues.',{override:clues});break;}
   case 'layout': s.layout=el.dataset.layout;render();break;
   case 'filter': s.eventFilter=el.dataset.type;action('event_filter',{value:s.eventFilter});render();break;
   case 'open-photo': showPhoto(el.dataset.id);break;
   case 'confirm-photo': confirmPhoto(el.dataset.id);break;
   case 'reject': rejectPhoto(el.dataset.id);break;
   case 'reject-modal': closeModal();rejectPhoto(el.dataset.id);break;
   case 'undo-reject': {const last=s.rejectedStack.pop();if(last){s.rejected=s.rejected.filter(id=>id!==last.id);if(last.result&&!s.results?.some(r=>r.id===last.id))s.results?.push(last.result);action('undo_reject',{photoId:last.id});render();}break;}
   case 'undo-confirm': {const a=attempt();if(a?.status==='confirmed'){a.status='active';a.selectedId=null;a.endedAt=null;a.actions.push({type:'undo_confirmation',at:Date.now()});persist();}closeModal();render();break;}
   case 'related': {const p=getPhoto(el.dataset.id);if(p)browseGroup(p.eventId||[p.eventType,p.date||'undated',p.setting].join(':'),true);break;}
   case 'browse-group': browseGroup(el.dataset.group);break;
   case 'close-modal': closeModal();break;
   case 'upload': showUpload();break;
   case 'import': await performImport();break;
   case 'index-pending': await indexPending();break;
   case 'confirm-index': await doIndex();break;
   case 'settings': showSettings();break;
   case 'save-settings': saveSettings();closeModal();render();toast('AI settings saved for this session.');break;
   case 'refresh-status': saveSettings();await checkStatus();showSettings();break;
   case 'test-ai': {saveSettings();el.disabled=true;$('#ai-test-result').textContent='Sending one sample-only test request…';try{const data=await api('/api/search',{query:'birthday',photos:[E.safePhoto(s.samples[0])],clues:[],rejected:[]});s.aiChecked=true;$('#ai-test-result').textContent=`Successful response from ${data.meta.model} in ${(data.meta.durationMs/1000).toFixed(1)}s. No personal photos were sent.`;updateShell();}catch(e){$('#ai-test-result').textContent=e.message;}finally{if(el.isConnected)el.disabled=false;}break;}
   case 'grant-consent': if(!$('#consent-confirm').checked){toast('Check the permission box before continuing.');break;}s.consent=true;closeModal();if(el.dataset.next==='search')await runSearch(s.pendingInput);break;
   case 'privacy': showPrivacy();break;
   case 'voice': voice();break;
   case 'retry': await runSearch(s.pendingInput||s.query);break;
   case 'fallback': await runSearch(s.pendingInput||s.query,{forceLocal:true});break;
   case 'cancel-search': cancelSearch();s.error='Search cancelled. No result was recorded. A provider call already sent may still be billable.';render();break;
   case 'abandon': endAttempt('abandoned');s.view='insights';render();break;
   case 'open-insights': closeModal();s.view='insights';render();break;
   case 'export-json': exportJSON();break;
   case 'export-csv': exportCSV();break;
   case 'clear-history': if(confirm('Delete search history from this browser? Export it first to keep your test observations.')){cancelSearch();s.attempts=[];s.attemptId=null;persist();resetSearch(false);render();}break;
   case 'clear-all': await clearAll();break;
   case 'restore': {const a=s.attempts.find(a=>a.id===el.dataset.id);if(a){resetSearch();s.collection=a.source;s.pendingTest=null;s.view='search';await runSearch(a.initialQuery);toast('Started a new attempt from that memory. The earlier trail is unchanged.');}break;}
   case 'test-setup': showTestSetup();break;
   case 'delete-photo': {const p=s.own.find(p=>p.id===el.dataset.id);if(p&&confirm('Delete this photo copy and its labels from this browser? Search history is separate and can be cleared in Search trail.')){await removePhoto(p.id);s.own=s.own.filter(x=>x.id!==p.id);s.results=s.results?.filter(r=>r.id!==p.id)??null;closeModal();render();toast('Browser photo copy deleted.');}break;}
  }
 }catch(e){toast(e.message||'Something went wrong. Please retry.');}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['search-form','edit-photo-form','test-form'].includes(form.id))return;event.preventDefault();
 try{
  if(form.id==='search-form'){await runSearch($('#memory-input').value);return;}
  if(form.id==='test-form'){const targetId=$('#test-target').value,participant=$('#test-code').value.trim();resetSearch();s.pendingTest={targetId,participant};s.view='search';closeModal();render();toast('Target set. Hand the screen to the participant; the timer starts with the first search.');return;}
  if(form.id==='edit-photo-form'){
   const p=s.own.find(p=>p.id===form.dataset.id);if(!p)return;
   const updated={...p,title:$('#edit-title').value.trim()||'Untitled photo',caption:$('#edit-caption').value.trim(),cues:$('#edit-cues').value.split(',').map(c=>c.trim()).filter(Boolean).slice(0,30),eventLabel:$('#edit-event').value.trim(),eventType:$('#edit-type').value,setting:$('#edit-setting').value,people:$('#edit-people').value.split(',').map(n=>n.trim()).filter(Boolean).slice(0,12),date:$('#edit-date').value,userEdited:true};updated.eventId=groupKey(updated);
   await storePhoto(updated);Object.assign(p,updated);action('metadata_edit',{photoId:p.id});closeModal();
   // Discard stale relevance evidence but preserve the task and its elapsed time.
   if(s.results){s.results=null;s.clues=[];s.query='';s.groupContext=null;}render();toast('Context saved. Run the search again to use the corrected description.');
  }
 }catch(e){toast(e.message||'Could not save. Please retry.');}
});
document.addEventListener('keydown',event=>{if(event.target.id==='memory-input'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();event.target.closest('form').requestSubmit();}});
document.addEventListener('change',event=>{if(event.target.id==='photo-files')selectFiles(event.target.files);if(event.target.id==='metrics-filter'){s.metricsSource=event.target.value;render();}});
document.addEventListener('dragover',event=>{const drop=event.target.closest('#dropzone');if(drop){event.preventDefault();drop.classList.add('drag');}});
document.addEventListener('dragleave',event=>event.target.closest('#dropzone')?.classList.remove('drag'));
document.addEventListener('drop',event=>{const drop=event.target.closest('#dropzone');if(drop&&!importBusy){event.preventDefault();drop.classList.remove('drag');selectFiles(event.dataTransfer.files);}});
$('#modal').addEventListener('cancel',event=>{if(importBusy){event.preventDefault();stopImport=true;toast('Stopping after the current operation.');}});
readHistory();
await loadPhotos();
await checkStatus();
render();
